<?php
 namespace OSS\Model; class DeletedObjectInfo { public function __construct($key, $versionId, $deleteMarker, $deleteMarkerVersionId) { $this->key = $key; $this->versionId = $versionId; $this->deleteMarker = $deleteMarker; $this->deleteMarkerVersionId = $deleteMarkerVersionId; } public function getKey() { return $this->key; } public function getVersionId() { return $this->versionId; } public function getDeleteMarker() { return $this->deleteMarker; } public function getDeleteMarkerVersionId() { return $this->deleteMarkerVersionId; } private $key = ""; private $versionId = ""; private $deleteMarker = ""; private $deleteMarkerVersionId = ""; }